/* =========================================================
   Aufgeräumtes Menü, Einstellungen, Farben passend zum Bild
   ========================================================= */
.nv-quick {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.nv-planbig {
  width: 100%;
  justify-content: center;
  min-height: 48px;
  margin: 2px 0 6px;
}
.nv-navrow span {
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.nv-rowsub {
  font-size: 12px;
  font-weight: 400;
  color: var(--soft);
}
.nv-navrow.hi {
  background: var(--ink);
  color: var(--bg2);
  border-color: transparent;
}
.nv-navrow.hi em {
  color: inherit;
  opacity: 0.75;
}
.nv-navrow:disabled {
  opacity: 0.45;
}
.nv-more-toggle {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 12px 2px;
  background: none;
  border: 0;
  border-top: 1px solid var(--line);
  color: var(--soft);
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
}
.nv-more-toggle svg {
  transition: transform 0.25s ease;
}
.nv-more-toggle[aria-expanded='true'] svg {
  transform: rotate(90deg);
}
/* Kopf: nur noch das Menü – rechts */
.nv-top {
  justify-content: flex-end;
}
.nv-ctx:empty {
  display: none;
}
/* Farbwechsel weich */
.nv-sheet,
.nv-dots,
.nv-navrow {
  transition: background-color 0.6s ease, color 0.6s ease, border-color 0.6s ease;
}

/* =========================================================
   Rad (Locker): frei scrollen, Mitte ist dran
   ========================================================= */
.nv-wheel {
  --wh: min(54vh, 440px);
  position: relative;
  height: var(--wh);
  overflow-y: auto;
  overscroll-behavior: contain;
  scroll-snap-type: y mandatory;
  scroll-padding-top: 30px;
  scrollbar-width: none;
  padding: 30px 2px calc(var(--wh) - 150px);
  margin: -30px -2px 0;
  -webkit-mask-image: linear-gradient(180deg, transparent 0, #000 30px, #000 70%, transparent 100%);
  mask-image: linear-gradient(180deg, transparent 0, #000 30px, #000 70%, transparent 100%);
}
.nv-wheel::-webkit-scrollbar {
  display: none;
}
.nv-wrow {
  scroll-snap-align: start;
  padding: 5px 0;
  transition: opacity 0.25s ease, transform 0.25s ease, filter 0.25s ease;
  transform-origin: 50% 0;
}
.nv-wrow.w0 {
  opacity: 1;
}
.nv-wrow.w1 {
  opacity: 0.6;
  transform: scale(0.96);
}
.nv-wrow.w2 {
  opacity: 0.32;
  transform: scale(0.92);
}
.nv-wrow.w3 {
  opacity: 0.16;
  transform: scale(0.88);
}
.nv-wrow:not(.w0) .nv-card {
  box-shadow: none;
}
.nv-wrow.w2,
.nv-wrow.w3 {
  cursor: pointer;
}
.nv-wrow.sout {
  opacity: 0;
  transform: translateX(40px) scale(0.95);
}
.nv-wheelhint {
  margin: 6px 0 0;
  text-align: center;
  font-size: 12px;
  color: var(--soft);
  font-variant-numeric: tabular-nums;
}
.nv.has-photo .nv-wheelhint {
  color: rgba(255, 255, 255, 0.8);
}
@media (prefers-reduced-motion: reduce) {
  .nv-wrow {
    transition: none;
  }
}

