}
.fx-batch button.on .fx-bchk {
  background: #fff;
  color: #1c1c1a;
  border-color: #fff;
}
.fx-btxt {
  flex: 1;
  line-height: 1.3;
}

/* Auswahl im Menü */
.bk-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
  max-height: 42vh;
  overflow-y: auto;
}
.bk-row {
  flex: none;
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 46px;
  padding: 10px 14px;
  border-radius: 14px;
  border: 1px solid var(--line);
  background: var(--glass);
  color: var(--ink);
  text-align: left;
  font-size: 15px;
  cursor: pointer;
}
.bk-row[aria-pressed='true'] {
  border-color: var(--ink);
  background: var(--glass2);
}
.bk-chk {
  flex: none;
  display: grid;
  place-items: center;
  width: 22px;
  height: 22px;
  border-radius: 6px;
  border: 1.5px solid var(--line2);
}
.bk-row[aria-pressed='true'] .bk-chk {
  background: var(--ink);
  border-color: var(--ink);
  color: var(--bg2);
}
.bk-txt {
  flex: 1;
  line-height: 1.3;
}
.bk-dot {
  flex: none;
  width: 8px;
  height: 8px;
  border-radius: 50%;
}
.bk-quick {
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
  margin-top: 10px;
}

/* App-Sperre: klarer An/Aus-Schalter */
.ct-power {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin: 16px 0 8px;
  padding: 14px 14px 14px 16px;
  border-radius: 16px;
  border: 1px solid var(--line2);
  background: var(--glass2);
}
.ct-power.on {
  border-color: var(--ok);
  background: color-mix(in srgb, var(--ok) 10%, var(--glass2));
}
.ct-power-l {
  display: flex;
  align-items: center;
  gap: 12px;
  min-width: 0;
}
.ct-power-l svg {
  flex: none;
  color: var(--soft);
}
.ct-power.on .ct-power-l svg {
  color: var(--ok);
}
.ct-power-l b {
  display: block;
  font-size: 15px;
  color: var(--ink);
}
.ct-power-l small {
  display: block;
  margin-top: 2px;
  font-size: 12.5px;
  line-height: 1.35;
  color: var(--soft);
}
.ct-power .nv-btn {
  flex: none;
  min-height: 42px;
}
.ct-offask {
  margin: 4px 0 10px;
}
.ct-err {
  margin: 6px 0 0;
  font-size: 13px;
  color: var(--urg);
}
.ct-saved {
  position: fixed;
  left: 50%;
  bottom: calc(18px + env(safe-area-inset-bottom));
  z-index: 80;
  display: flex;
  align-items: center;
  gap: 6px;
  width: max-content;
  margin: 0;
  translate: -50% 0;
  padding: 7px 12px;
  border-radius: 999px;
  background: var(--ink);
  color: var(--bg2);
  font-size: 13px;
  animation: ct-pop 0.25s ease both;
}
@keyframes ct-pop {
  from {
    opacity: 0;
    transform: translateY(6px);
  }
  to {
    opacity: 1;
    transform: none;
  }
